#!/usr/bin/env bash
# lib/vfio_config.sh - VFIO driver configuration, module loading, and GRUB bootloader updates

generate_vfio_modprobe() {
    local device_ids="$1" # comma-separated list of vendor:device IDs
    cat <<EOF
# Generated by VFIO Looking-Glass Setup Toolkit
# Isolate GPU and Audio controllers for VFIO passthrough
options vfio-pci ids=${device_ids}

# Ensure vfio-pci loads before host graphics drivers
softdep nouveau pre: vfio-pci
softdep nvidia pre: vfio-pci
softdep nvidia_drm pre: vfio-pci
softdep amdgpu pre: vfio-pci
softdep radeon pre: vfio-pci
EOF
}

generate_initramfs_modules() {
    cat <<EOF
# VFIO Passthrough modules
vfio
vfio_iommu_type1
vfio_pci
EOF
}

configure_vfio_modprobe() {
    local device_ids="$1"
    local conf_file="/etc/modprobe.d/vfio.conf"

    log_step "Configuring VFIO modprobe: ${conf_file}"
    local content
    content=$(generate_vfio_modprobe "$device_ids")
    safe_write "$content" "$conf_file"

    local blacklist_file="/etc/modprobe.d/blacklist-nvidia-vfio.conf"
    log_step "Configuring VFIO blacklist to prevent host module storms: ${blacklist_file}"
    local blacklist_content
    blacklist_content=$(cat <<'EOF'
# Blacklist NVIDIA host modules to protect VFIO passthrough and prevent modprobe storms
blacklist nvidia
blacklist nvidia_drm
blacklist nvidia_modeset
blacklist nvidia_uvm
blacklist nouveau

install nvidia /bin/true
install nvidia_drm /bin/true
install nvidia_modeset /bin/true
install nvidia_uvm /bin/true
EOF
)
    safe_write "$blacklist_content" "$blacklist_file"

    # Mask runaway NVIDIA udev rules if present
    if [[ -f "/lib/udev/rules.d/71-nvidia.rules" ]]; then
        log_step "Masking /lib/udev/rules.d/71-nvidia.rules in /etc/udev/rules.d/"
        if [[ ! -e "/etc/udev/rules.d/71-nvidia.rules" ]]; then
            ln -sf /dev/null /etc/udev/rules.d/71-nvidia.rules
        fi
    fi

    # Mask host NVIDIA services that cause crash-loops under VFIO
    for s in nvidia-persistenced.service nvidia-suspend.service nvidia-resume.service nvidia-hibernate.service; do
        if systemctl list-unit-files "$s" &>/dev/null; then
            systemctl mask "$s" 2>/dev/null || true
        fi
    done
}

configure_initramfs_modules() {
    local modules_file="/etc/initramfs-tools/modules"
    local alt_modules_file="/etc/modules-load.d/vfio.conf"

    if [[ -d "/etc/initramfs-tools" ]]; then
        log_step "Updating ${modules_file}"
        if [[ "${DRY_RUN:-0}" -eq 1 ]]; then
            log_info "[DRY-RUN] Would append vfio modules to ${modules_file} if not present"
        else
            backup_file "$modules_file"
            for mod in vfio vfio_iommu_type1 vfio_pci; do
                if ! grep -qE "^${mod}\b" "$modules_file" 2>/dev/null; then
                    if [[ $EUID -ne 0 && ! -w "$modules_file" ]]; then
                        echo "$mod" | sudo tee -a "$modules_file" >/dev/null
                    else
                        echo "$mod" >> "$modules_file"
                    fi
                    log_info "Added '$mod' to ${modules_file}"
                fi
            done
        fi
    fi

    # Also place in modules-load.d for systemd
    log_step "Configuring ${alt_modules_file}"
    local content
    content=$(generate_initramfs_modules)
    safe_write "$content" "$alt_modules_file"
}

configure_grub_cmdline() {
    local iommu_param="$1" # e.g. intel_iommu=on iommu=pt
    local grub_file="/etc/default/grub"

    if [[ ! -f "$grub_file" ]]; then
        log_warn "GRUB configuration file not found at ${grub_file}."
        log_info "Please ensure the following kernel parameters are set in your bootloader:"
        log_info "  ${iommu_param} kvm.ignore_msrs=1"
        return 0
    fi

    log_step "Updating GRUB kernel parameters in ${grub_file}"

    # Check if parameters already present in GRUB_CMDLINE_LINUX_DEFAULT
    local current_line
    current_line=$(grep '^GRUB_CMDLINE_LINUX_DEFAULT=' "$grub_file" || true)

    local params_to_add=()
    for p in $iommu_param "kvm.ignore_msrs=1"; do
        if ! grep -q "$p" <<< "$current_line"; then
            params_to_add+=("$p")
        fi
    done

    if [[ ${#params_to_add[@]} -eq 0 ]]; then
        log_info "All required IOMMU parameters already present in ${grub_file}."
        return 0
    fi

    local append_str="${params_to_add[*]}"
    log_info "Parameters to append: ${COLOR_BOLD}${append_str}${COLOR_RESET}"

    if [[ "${DRY_RUN:-0}" -eq 1 ]]; then
        log_info "[DRY-RUN] Would update GRUB_CMDLINE_LINUX_DEFAULT with '${append_str}'"
        return 0
    fi

    backup_file "$grub_file"

    local sudo_cmd=""
    if [[ $EUID -ne 0 && ! -w "$grub_file" ]]; then
        sudo_cmd="sudo"
    fi

    # Safely insert parameters inside quotes of GRUB_CMDLINE_LINUX_DEFAULT
    $sudo_cmd sed -i.tmp -E "s/^(GRUB_CMDLINE_LINUX_DEFAULT=\"[^\"]*)/\1 ${append_str}/" "$grub_file"
    $sudo_cmd rm -f "${grub_file}.tmp"

    log_success "Updated ${grub_file} successfully."
}

update_system_boot() {
    if [[ "${DRY_RUN:-0}" -eq 1 ]]; then
        log_info "[DRY-RUN] Would execute 'update-initramfs -u' and 'update-grub'"
        return 0
    fi

    local sudo_cmd=""
    if [[ $EUID -ne 0 ]]; then
        sudo_cmd="sudo"
    fi

    log_step "Rebuilding initramfs and updating bootloader"
    if command -v update-initramfs >/dev/null 2>&1; then
        log_info "Running update-initramfs -u..."
        $sudo_cmd update-initramfs -u
        log_success "Initramfs updated."
    elif command -v dracut >/dev/null 2>&1; then
        log_info "Running dracut --force..."
        $sudo_cmd dracut --force
        log_success "Dracut initramfs updated."
    fi

    if command -v update-grub >/dev/null 2>&1; then
        log_info "Running update-grub..."
        $sudo_cmd update-grub
        log_success "GRUB updated."
    elif command -v grub-mkconfig >/dev/null 2>&1; then
        log_info "Running grub-mkconfig..."
        $sudo_cmd grub-mkconfig -o /boot/grub/grub.cfg
        log_success "GRUB configuration re-generated."
    fi
}

enable_vfio_mode() {
    require_root
    log_header "Switching GPU to VM Passthrough Mode (VFIO)"

    local vfio_conf="/etc/modprobe.d/vfio.conf"
    local vfio_conf_dis="/etc/modprobe.d/vfio.conf.disabled"
    local bl_conf="/etc/modprobe.d/blacklist-nvidia-vfio.conf"
    local bl_conf_dis="/etc/modprobe.d/blacklist-nvidia-vfio.conf.disabled"

    if [[ -f "$vfio_conf_dis" ]]; then
        mv -f "$vfio_conf_dis" "$vfio_conf"
        log_success "Restored ${vfio_conf}"
    elif [[ ! -f "$vfio_conf" ]]; then
        configure_vfio_modprobe "10de:24dc,10de:228b"
    fi

    if [[ -f "$bl_conf_dis" ]]; then
        mv -f "$bl_conf_dis" "$bl_conf"
        log_success "Restored ${bl_conf}"
    fi

    configure_initramfs_modules

    log_step "Updating initramfs..."
    update-initramfs -u
    log_success "VFIO Mode Enabled! RTX 3080 will bind to vfio-pci upon next reboot."
    log_info "After reboot, simply run 'win11' to start your high-performance VM."
}

disable_vfio_mode() {
    require_root
    log_header "Switching GPU to Linux Host Mode (NVIDIA)"

    local vfio_conf="/etc/modprobe.d/vfio.conf"
    local vfio_conf_dis="/etc/modprobe.d/vfio.conf.disabled"
    local bl_conf="/etc/modprobe.d/blacklist-nvidia-vfio.conf"
    local bl_conf_dis="/etc/modprobe.d/blacklist-nvidia-vfio.conf.disabled"

    if [[ -f "$vfio_conf" ]]; then
        mv -f "$vfio_conf" "$vfio_conf_dis"
        log_success "Disabled ${vfio_conf} -> ${vfio_conf_dis}"
    fi

    if [[ -f "$bl_conf" ]]; then
        mv -f "$bl_conf" "$bl_conf_dis"
        log_success "Disabled ${bl_conf} -> ${bl_conf_dis}"
    fi

    log_step "Updating initramfs..."
    update-initramfs -u
    log_success "Host Mode Enabled! RTX 3080 will bind to nvidia driver upon next reboot."
    log_info "Host applications (Blender, CUDA, Ollama) will have direct GPU access."
}

show_gpu_mode_status() {
    log_header "GPU Passthrough & Mode Status"
    
    local gpu_driver=""
    local audio_driver=""
    if [[ -d "/sys/bus/pci/devices/0000:01:00.0/driver" ]]; then
        gpu_driver=$(basename "$(readlink /sys/bus/pci/devices/0000:01:00.0/driver)")
    fi
    if [[ -d "/sys/bus/pci/devices/0000:01:00.1/driver" ]]; then
        audio_driver=$(basename "$(readlink /sys/bus/pci/devices/0000:01:00.1/driver)")
    fi

    printf "  • RTX 3080 GPU (0000:01:00.0):   ${COLOR_BOLD}%s${COLOR_RESET}\n" "${gpu_driver:-unbound}"
    printf "  • GA104 Audio  (0000:01:00.1):   ${COLOR_BOLD}%s${COLOR_RESET}\n" "${audio_driver:-unbound}"
    
    local vfio_cfg_status="NOT INSTALLED"
    if [[ -f "/etc/modprobe.d/vfio.conf" ]]; then
        vfio_cfg_status="${COLOR_GREEN}ENABLED (VM Mode)${COLOR_RESET}"
    elif [[ -f "/etc/modprobe.d/vfio.conf.disabled" ]]; then
        vfio_cfg_status="${COLOR_YELLOW}DISABLED (Host Mode)${COLOR_RESET}"
    fi
    printf "  • VFIO Boot Config:              %s\n" "$vfio_cfg_status"

    local iommu_status="${COLOR_RED}INACTIVE${COLOR_RESET}"
    if [[ -d "/sys/kernel/iommu_groups" && $(ls -A /sys/kernel/iommu_groups 2>/dev/null | wc -l) -gt 0 ]]; then
        iommu_status="${COLOR_GREEN}ACTIVE (IOMMU enabled in kernel)${COLOR_RESET}"
    fi
    printf "  • Kernel IOMMU:                  %s\n" "$iommu_status"

    local vm_state="shut off"
    if command -v virsh >/dev/null 2>&1; then
        vm_state=$(virsh -c qemu:///system domstate win11 2>/dev/null || echo "not defined")
    fi
    printf "  • 'win11' VM State:              ${COLOR_BOLD}%s${COLOR_RESET}\n\n" "$vm_state"

    if [[ "$gpu_driver" == "vfio-pci" ]]; then
        log_success "Status: Ready for Windows 11 VFIO Passthrough with Looking Glass!"
    else
        log_info "Status: GPU is currently in Host Mode (Linux owns RTX 3080)."
        log_info "To switch to VM mode:  sudo vfio-ctl --mode-vm"
    fi
}
